/** Kiro CLI effort levels accepted by both `chat` and `acp`. */
export const KIRO_REASONING_EFFORTS = [
  { id: 'low', name: 'Low', description: 'Fastest responses with the least reasoning.' },
  { id: 'medium', name: 'Medium', description: 'Balanced speed and reasoning depth.' },
  { id: 'high', name: 'High', description: 'More deliberate reasoning for complex work.' },
  { id: 'xhigh', name: 'Extra High', description: 'Maximum depth short of the full maximum setting.' },
  { id: 'max', name: 'Maximum', description: 'Highest available reasoning effort.' },
] as const

/** One Kiro CLI effort id accepted by `--effort`. */
export type KiroReasoningEffort = (typeof KIRO_REASONING_EFFORTS)[number]['id']
